      <div key={lineIndex}>
        {line.map((part, index) =>
          typeof part === "string" ? (
            <span key={index}>{part}</span>
          ) : (
            <span key={index} className="rounded-tau-sm bg-accent-soft px-0.5 text-accent-text">
              {part.mark}
            </span>
          )
        )}
      </div>
    ))}
  </code>
);

const COLOR = "#ccc";
const LAYERS = [
  { key: "vertical", label: "垂直线条", direction: "to right" },
  { key: "horizontal", label: "水平线条", direction: "to bottom" },
];

const Component = () => {
  const [cell, setCell] = useState(20);
  const [line, setLine] = useState(1);
  const [visible, setVisible] = useState({ vertical: true, horizontal: true });
  const layers = LAYERS.filter(layer => visible[layer.key]);
  const layerOf = direction =>
    `repeating-linear-gradient(${direction}, ${COLOR}, ${COLOR} ${line}px, transparent ${line}px, transparent ${cell}px)`;
  const toggle = key => setVisible(state => ({ ...state, [key]: !state[key] }));

  return (
    <Lab
      stage={
        <div
          className="relative h-[200px] w-full overflow-hidden rounded-tau-sm border border-line-1"
          style={{ backgroundImage: layers.length ? layers.map(layer => layerOf(layer.direction)).join(", ") : "none" }}
        >
          <div
            className="pointer-events-none absolute rounded-tau-sm border-2 border-accent transition-all duration-300 ease-tau-out"
            style={{ left: cell * 2 - 2, top: cell * 2 - 2, width: cell + line + 4, height: cell + line + 4 }}
          />
        </div>
      }
      code={
        <Code
          lines={[
            [layers.length ? "background-image:" : "background-image: none;"],
            ...layers.flatMap((layer, index) => [
              [`  /* ${layer.label} */`],
              [
                `  repeating-linear-gradient(${layer.direction}, ${COLOR}, ${COLOR} `,
                { mark: `${line}px` },
                ", transparent ",
                `${line}px`,
                ", transparent ",
                { mark: `${cell}px` },
                index === layers.length - 1 ? ");" : "),",
              ],
            ]),
          ]}
        />
      }
    >
      <div className="flex flex-col gap-1.5">
        <span className="text-tau-sm text-ink-3">背景层</span>
        <div className="flex flex-wrap gap-1.5">
          {LAYERS.map(layer => (
            <button
              key={layer.key}
              type="button"
              aria-pressed={visible[layer.key]}
              onClick={() => toggle(layer.key)}
              className={`cursor-pointer rounded-tau-sm border px-2 py-0.5 text-tau-sm transition-colors ${
                visible[layer.key] ? "border-accent bg-accent-soft text-accent-text" : "border-line-1 bg-surface text-ink-2 hover:bg-hover"
              }`}
            >
              {layer.label}
            </button>
          ))}
        </div>
      </div>
      <Slider label="格子大小" value={cell} min={8} max={40} onChange={setCell} format={value => `${value}px`} />
      <Slider label="线宽" value={line} min={1} max={4} onChange={setLine} format={value => `${value}px`} />
      <Readout
        rows={[
          ["一个周期", `${cell}px`],
          ["叠加层数", `${layers.length}`],
        ]}
      />
      <span className="text-tau-meta text-ink-3">描边框出的是一个周期：线条加透明间隔。</span>
    </Lab>
  );
};
